             S-01,old stressor,old change,system handles old,auth,A-01\n",
        )
        .unwrap();
        let loaded = load(dir.path()).unwrap();
        assert_eq!(loaded.len(), 1);
        assert_eq!(
            loaded[0].shortname, "",
