use anyhow::Result;
use std::fs;
use crate::config::Config;
use crate::cli::{AddTarget, ListTarget};
use crate::structure::analysis::residues::{tag_naive_change_whole_system, Residue};

pub mod attractors;
pub mod config;
pub mod format;
pub mod integrity;
pub mod iterations;
pub mod personas;
pub mod purposes;
pub mod residues;
pub mod research;
pub mod stressors;
pub mod terminology;

const WHOLE_SYSTEM_REMINDER: &str = "reminder: examine whole-system-residue (hardware, process, organization, policy) before defaulting to a software-only patch; use --whole-system --notes when the zig survives outside software";

pub fn init(cfg: &Config, force: bool) -> Result<()> {
    let session = integrity::sessions::begin_mutation(&cfg.residual_dir, force)?;
    init_dirs_and_files(cfg)?;
    session.commit()?;
    println!("Initialized residual/ at {}", cfg.residual_dir.display());
    Ok(())
}

fn init_dirs_and_files(cfg: &Config) -> Result<()> {
    let dir = &cfg.residual_dir;
    fs::create_dir_all(dir.join("iterations"))?;
    fs::create_dir_all(dir.join("personas"))?;
    fs::create_dir_all(dir.join("research"))?;

    // Write v3 config.toml if not present (storage-config owns app + verify policy).
    let config_path = dir.join("config.toml");
    if !config_path.exists() {
        let toml = crate::storage::config::render_v3(&crate::storage::config::StorageConfig::default());
        fs::write(&config_path, toml)?;
    }

    // Write empty CSVs with headers if not present
    let csvs: &[(&str, &str)] = &[
        ("stressors.csv", "id,shortname,description,naive_change,outcomes,components_affected,attractor_id"),
        ("purposes.csv", "id,shortname,description,feature,outcomes,components_enabled,attractor_id"),
        ("attractors.csv", "id,name,description,positive_state,negative_state"),
        ("terminology.csv", "term,definition,domain,related_terms"),
        ("forces.csv", "id,kind,shortname,naive_change,outcomes,description,attractor_id"),
        ("lexicon.csv", "term,definition,domain,aliases"),
        ("residues.csv", "force"),
        ("components.csv", "name,description,status,architecture_set"),
    ];
    for (filename, header) in csvs {
        let path = dir.join(filename);
        if !path.exists() {
            fs::write(&path, format!("{}\n", header))?;
        }
    }
    Ok(())
}

pub fn add(cfg: &Config, target: AddTarget, force: bool) -> Result<()> {
    let session = integrity::sessions::begin_mutation(&cfg.residual_dir, force)?;
    add_entry(cfg, target)?;
    session.commit()?;
    Ok(())
}

fn add_entry(cfg: &Config, target: AddTarget) -> Result<()> {
    let dir = &cfg.residual_dir;
    match target {
        AddTarget::Stressor {
            description,
            attractor_id,
            naive_change,
            outcomes,
            components,
            whole_system,
            notes,
        } => {
            let naive_change = if whole_system {
                if notes.is_empty() {
                    anyhow::bail!("--whole-system requires --notes describing the hardware, process, organization, or policy zig");
                }
                tag_naive_change_whole_system(&naive_change)
            } else {
                eprintln!("{WHOLE_SYSTEM_REMINDER}");
                naive_change
            };
            let existing = stressors::load(dir)?;
            let id = stressors::next_id(&existing);
            stressors::append(dir, stressors::Stressor {
                id: id.clone(),
                shortname: String::new(),
                description,
                attractor_id,
                naive_change,
                outcomes,
                components_affected: components,
            })?;
            if whole_system {
                let residue_id = residues::append_whole_system(dir, &id, &notes)?;
                println!("Added whole-system-residue {}", residue_id);
            }
            println!("Added stressor {}", id);
        }
        AddTarget::Residue {
            force_id,
            component_id,
            status,
            notes,
            whole_system,
        } => {
            if whole_system {
                let id = residues::append_whole_system(dir, &force_id, &notes)?;
                println!("Added whole-system-residue {}", id);
            } else {
                if component_id.is_empty() {
                    anyhow::bail!("provide --component-id or --whole-system");
                }
                if !residues::force_exists(dir, &force_id)? {
                    anyhow::bail!("force id '{}' not found in stressors, purposes, or forces", force_id);
                }
                let existing = residues::load(dir)?;
                let id = residues::next_id(&existing);
                residues::append(
                    dir,
                    Residue {
                        id: id.clone(),
                        force_id,
                        component_id,
                        status,
                        notes,
                    },
                )?;
                println!("Added residue {}", id);
            }
        }
        AddTarget::Purpose { description, attractor_id, feature, outcomes, components } => {
            let existing = purposes::load(dir)?;
            let id = purposes::next_id(&existing);
            purposes::append(dir, purposes::Purpose {
                id: id.clone(),
                shortname: String::new(),
                description,
                attractor_id,
                feature,
                outcomes,
                components_enabled: components,
            })?;
            println!("Added purpose {}", id);
        }
        AddTarget::Attractor {
            name,
            description,
            positive_state,
            negative_state,
        } => {
            let existing = attractors::load(dir)?;
            let id = attractors::next_id(&existing);
            attractors::append(
                dir,
                attractors::Attractor {
                    id: id.clone(),
                    name,
                    description,
                    positive_state,
                    negative_state,
                },
            )?;
            println!("Added attractor {}", id);
        }
        AddTarget::Term { term, definition, domain, related } => {
            terminology::append(dir, terminology::Term {
                term: term.clone(),
                definition,
                domain,
                related_terms: related,
            })?;
            println!("Added term '{}'", term);
        }
        AddTarget::Persona { name, role, concerns, desires } => {
            personas::create(dir, personas::Persona {
                name: name.clone(),
                role,
                concerns,
                desires,
                stressor_ids: vec![],
            })?;
            println!("Added persona '{}'", name);
        }
        AddTarget::Iteration { notes, ri_score } => {
            let n = iterations::next_n(dir)?;
            let date = chrono::Local::now().format("%Y-%m-%d").to_string();
            iterations::create(dir, iterations::IterationMeta {
                n,
                date,
                ri_score,
                n_val: String::new(),
                k_val: String::new(),
                p_val: String::new(),
                notes,
            })?;
            println!("Added iteration {}", n);
        }
    }
    Ok(())
}

pub fn list(cfg: &Config, target: ListTarget) -> Result<()> {
    let dir = &cfg.residual_dir;
    match target {
        ListTarget::Stressors => {
            let items = stressors::load(dir)?;
            if items.is_empty() {
                println!("No stressors.");
            } else {
                for s in &items {
                    println!("[{}] {} (attractor: {})", s.id, s.description, s.attractor_id);
                }
            }
        }
        ListTarget::Purposes => {
            let items = purposes::load(dir)?;
            if items.is_empty() {
                println!("No purposes.");
            } else {
                for p in &items {
                    let extra = if p.outcomes.is_empty() { String::new() } else { format!(" | outcomes: {}", p.outcomes) };
                    println!("[{}] {} (naive_change: {}{})", p.id, p.description, p.feature, extra);
                }
            }
        }
        ListTarget::Attractors => {
            let items = attractors::load(dir)?;
            if items.is_empty() {
                println!("No attractors.");
            } else {
                for a in &items {
                    println!(
                        "[{}] {} (+/{} | -/{} )",
                        a.id,
                        a.name,
                        truncate_state(&a.positive_state),
                        truncate_state(&a.negative_state)
                    );
                }
            }
        }
        ListTarget::Terminology => {
            let items = terminology::load(dir)?;
            if items.is_empty() {
                println!("No terminology.");
            } else {
                for t in &items {
                    println!("{}: {}", t.term, t.definition);
                }
            }
        }
        ListTarget::Personas => {
            let names = personas::list_names(dir)?;
            if names.is_empty() {
                println!("No personas.");
            } else {
                for name in &names {
                    println!("{}", name);
                }
            }
        }
        ListTarget::Residues => { let matrix = format::format_residues_matrix(dir)?; if matrix.lines().count()<=1 { println!("No residues."); } else { print!("{matrix}"); } }
        ListTarget::Iterations => {
            let items = iterations::list(dir)?;
            if items.is_empty() {
                println!("No iterations.");
            } else {
                let mut sorted = items;
                sorted.sort_by_key(|i| i.n);
                for meta in &sorted {
                    println!("Iteration {}: {} (Ri: {})", meta.n, meta.date, meta.ri_score);
                }
            }
        }
    }
    Ok(())
}

fn truncate_state(s: &str) -> String {
    const MAX: usize = 40;
    if s.chars().count() <= MAX {
        s.to_string()
    } else {
        let mut out: String = s.chars().take(MAX).collect();
        out.push('…');
        out
    }
}

/// Run naive → v3 migration for the project's residual/ directory.
pub fn migrate(cfg: &Config, force: bool) -> Result<()> {
    let report = integrity::migration::migrate_residual_dir(&cfg.residual_dir, force)?;
    println!(
        "Migrated {} → v3 (config={}, forces={}, residues={}, attractors={}, lexicon={})",
        cfg.residual_dir.display(),
        report.config_migrated,
        report.forces,
        report.residues,
        report.attractors,
        report.lexicon_terms
    );
    if !report.unmapped_components.is_empty() {
        println!(
            "Unmapped naive component tokens (left as-is): {}",
            report.unmapped_components.join(", ")
        );
    }
    Ok(())
}

use anyhow::Result;
use crate::config::Config;

pub fn build(cfg: &Config, skill_name: &str) -> Result<String> {
    let dir = &cfg.residual_dir;

    let attractors = crate::storage::attractors::load(dir).unwrap_or_default();
    let stressors  = crate::storage::stressors::load(dir).unwrap_or_default();
    let purposes   = crate::storage::purposes::load(dir).unwrap_or_default();
    let terms      = crate::storage::terminology::load(dir).unwrap_or_default();
    let personas   = crate::storage::personas::load_all(dir).unwrap_or_default();

    // NKP summary: N = stressors + unique components (matrix semantics), not entity bag count.
    let mut component_set = std::collections::BTreeSet::new();
    for s in &stressors {
        for c in s.components_affected.split(',') {
            let c = c.trim();
            if !c.is_empty() {
                component_set.insert(c.to_string());
            }
        }
    }
    for p in &purposes {
        for c in p.components_enabled.split(',') {
            let c = c.trim();
            if !c.is_empty() {
                component_set.insert(c.to_string());
            }
        }
    }
    let n = stressors.len() + component_set.len();
    let k: usize = stressors
        .iter()
        .map(|s| {
            s.components_affected
                .split(',')
                .filter(|c| !c.trim().is_empty())
                .count()
        })
        .sum();
    let k_per_n = if n == 0 { 0.0 } else { k as f64 / n as f64 };

    let want_attractors;
    let want_stressors;
    let want_purposes;
    let want_terminology;
    let want_personas;
    let want_nkp;

    match skill_name {
        "purpose-walk" => {
            want_attractors  = true;
            want_stressors   = false;
            want_purposes    = true;
            want_terminology = true;
            want_personas    = false;
            want_nkp         = false;
        }
        "stressor-walk" => {
            want_attractors  = true;
            want_stressors   = true;
            want_purposes    = true;
            want_terminology = true;
            want_personas    = true;
            want_nkp         = false;
        }
        "integrate" => {
            want_attractors  = true;
            want_stressors   = true;
            want_purposes    = true;
            want_terminology = true;
            want_personas    = false;
            want_nkp         = true;
        }
        "fmea" | "atam" => {
            want_attractors  = true;
            want_stressors   = true;
            want_purposes    = true;
            want_terminology = true;
            want_personas    = true;
            want_nkp         = true;
        }
        "naive-draft" => {
            want_attractors  = false;
            want_stressors   = false;
            want_purposes    = true;
            want_terminology = true;
            want_personas    = false;
            want_nkp         = false;
        }
        _ => {
            // default: everything
            want_attractors  = true;
            want_stressors   = true;
            want_purposes    = true;
            want_terminology = true;
            want_personas    = true;
            want_nkp         = true;
        }
    }

    let mut out = String::new();
    out.push_str(&format!("# Residual Context — {}\n\n", skill_name));
    out.push_str(&verify_status_section(cfg)?);
    out.push_str(
        "## Fluent capture\n\
         Metadata (`residual add stressor|purpose|attractor|term|persona`) works in **any order**, \
         at **any phase**, without invoking a skill. Skills are **selectable analytical lenses** — \
         not mandatory gates. `verify all` enforces structure, not ceremony order.\n\n",
    );
    if matches!(skill_name, "stressor-walk" | "fmea" | "integrate") {
        out.push_str("## Whole-system-residue\n");
        out.push_str(
            "Examine **whole-system-residue** (hardware, process, organization, policy zig) \
             before defaulting to a software-only patch. Use `--whole-system --notes` when the \
             surviving change leaves the software boundary.\n\n",
        );
    }
    if want_personas {
        let persona_names: Vec<&str> = personas.iter().map(|p| p.name.as_str()).collect();
        if matches!(skill_name, "stressor-walk" | "fmea" | "atam") {
            if let Err(e) = crate::verification::check_personas_adequacy(&persona_names) {
                out.push_str(&format!(
                    "> **Persona note:** {} — add personas when ready; capture is not blocked.\n\n",
                    e
                ));
            }
        }
    }

    if want_attractors {
        out.push_str("## Attractors\n");
        out.push_str("| id | name | positive_state | negative_state |\n");
        out.push_str("|---|---|---|---|\n");
        for a in &attractors {
            out.push_str(&format!(
                "| {} | {} | {} | {} |\n",
                a.id, a.name, a.positive_state, a.negative_state
            ));
        }
        out.push('\n');
    }

    if want_stressors {
        out.push_str("## Stressors\n");
        out.push_str("| id | description | attractor_id | components |\n");
        out.push_str("|---|---|---|---|\n");
        for s in &stressors {
            out.push_str(&format!(
                "| {} | {} | {} | {} |\n",
                s.id, s.description, s.attractor_id, s.components_affected
            ));
        }
        out.push('\n');
    }

    if want_purposes {
        out.push_str("## Purposes\n");
        out.push_str("| id | description | attractor_id | naive_change | outcomes |\n");
        out.push_str("|---|---|---|---|---|\n");
        for p in &purposes {
            out.push_str(&format!(
                "| {} | {} | {} | {} | {} |\n",
                p.id, p.description, p.attractor_id, p.feature, p.outcomes
            ));
        }
        out.push('\n');
    }

    if want_terminology {
        out.push_str("## Terminology\n");
        out.push_str("| term | definition |\n");
        out.push_str("|---|---|\n");
        for t in &terms {
            out.push_str(&format!("| {} | {} |\n", t.term, t.definition));
        }
        out.push('\n');
    }

    if want_personas {
        out.push_str("## Personas\n");
        if personas.is_empty() {
            out.push_str("none\n");
        } else {
            for p in &personas {
                out.push_str(&format!("- {} (role: {})\n", p.name, p.role));
            }
        }
        out.push('\n');
    }

    if want_nkp {
        out.push_str("## NKP Summary\n");
        out.push_str(&format!("N={}, K={}, K/N={:.2}\n", n, k, k_per_n));
        out.push('\n');
    }

    Ok(out)
}

/// Socratic verify guidance: strict → fix with operator first; else note and proceed.
fn verify_status_section(cfg: &Config) -> Result<String> {
    let outcome_violations = crate::verify::check_outcomes(cfg).unwrap_or_default();
    let link_violations = crate::verify::check_links(cfg).unwrap_or_default();
    let total = outcome_violations.len() + link_violations.len();
    let strict = cfg.validation.strict;

    let mut out = String::new();
    out.push_str("## Verify status\n");
    out.push_str(&format!(
        "Policy: `super_strict` / validation.strict = **{}**\n\n",
        strict
    ));

    if total == 0 {
        out.push_str("Ledger checks passed. Proceed Socratically with the skill.\n\n");
        return Ok(out);
    }

    out.push_str(&format!(
        "**{total}** verify finding(s) ({} outcome, {} link):\n",
        outcome_violations.len(),
        link_violations.len()
    ));
    for v in outcome_violations.iter().take(8) {
        out.push_str(&format!(
            "- outcome [{}] {}: {} — {}\n",
            v.source, v.id, v.outcome_str, v.reason
        ));
    }
    for v in link_violations.iter().take(8) {
        out.push_str(&format!("- link [{}] {}: {}\n", v.source, v.id, v.message));
    }
    if total > 16 {
        out.push_str(&format!("- …and {} more (run `residual verify all`)\n", total - 16));
    }
    out.push('\n');

    if strict {
        out.push_str(
            "**Strict mode — fix before analysis.** Work Socratically with the operator: \
             propose concrete `residual add` / edits that clear these findings, wait for approval, \
             re-run `residual verify all`, then continue the skill. Do not invent architecture on a broken baseline.\n\n",
        );
    } else {
        out.push_str(
            "**Advisory mode — note and proceed.** Surface these findings to the operator, then jump into the skill. \
             Repair when ready; capture is not blocked. Still Socratic: gather freely, modify only with approval.\n\n",
        );
    }
    Ok(out)
}

